    private static function address(string $a):string {$t=mb_strtolower($a,'UTF-8');$t=str_replace(['ё','москва','улица','ул.'],['е','','',''],$t);$t=preg_replace('/[\s,]+/u','',$t);$t=str_replace(['корпус','корп.','строение','стр.'],['к','к','с','с'],$t);return preg_match('/^мосфильмовская\d+[а-я]?(?:[кс]\d+)*$/u',$t)?$t:preg_replace('/\s+/u','',mb_strtolower($a,'UTF-8'));}
    public static function coverage(array $s,string $source,string $kind,string $scope):array {
        $settings=$s['settings'];if(empty($settings['sources'][$source]['enabled'])||!in_array($kind,$settings['types'],true))return ['state'=>'not_checked','reason'=>'Источник или тип отключён в этом запуске.'];
        $attempts=array_values(array_filter($s['attempts'],fn($a)=>($a['source']??null)===$source&&($a['object_type']??null)===$kind&&($a['scope']??null)===$scope));
        if(count($attempts)!==1)return ['state'=>'limited','reason'=>'Нет однозначного результата проверки этой группы.'];$a=$attempts[0];if(($a['outcome']??null)==='unsupported')return ['state'=>'not_checked','reason'=>'Отдельный раздел не поддерживается сборщиком.'];
        $failed=in_array($a['outcome']??null,['blocked','failed'],true)||!empty($a['partial']);foreach($a['events']??[]as $e)if(in_array($e['outcome']??null,['blocked','failed'],true))$failed=true;
        if($failed)return ['state'=>'limited','reason'=>'Проверка неполна: лимит, блокировка или ошибка источника.'];
        if(!in_array($a['outcome']??null,['extracted','no_matching_listings'],true))return ['state'=>'limited','reason'=>'Результат проверки не подтверждает сопоставимую выборку.'];return ['state'=>'comparable','reason'=>'Проверенные заданные страницы; полный рынок не подтверждён.'];
    }
    private static function relevant(array $s,string $source,string $kind):array {$v=$s['settings'];return ['geography'=>$v['geography']??null,'filters'=>$v['filters'][$kind]??null,'seeds'=>$v['sources'][$source][$kind.'_urls']??null,'limits'=>$v['limits']??null,'browser'=>$v['browser']??null,'collector_code'=>$s['code_sha256']??(isset($s['collector_sha256'])?['collector'=>$s['collector_sha256']]:null)];}
    public static function pairCoverage(array $a,array $b,string $source,string $kind,string $scope):array {
        $left=self::coverage($a,$source,$kind,$scope);$right=self::coverage($b,$source,$kind,$scope);if(in_array('not_checked',[$left['state'],$right['state']],true))return ['state'=>'not_checked','reason'=>'Не проверялось в одном из запусков.'];$l=self::relevant($a,$source,$kind);$r=self::relevant($b,$source,$kind);
        if(!$l['collector_code']||!$r['collector_code'])return ['state'=>'limited','reason'=>'В одном из снимков не подтверждена версия сборщика.'];if(Market::canonical($l)!==Market::canonical($r))return ['state'=>'limited','reason'=>'Различаются настройки или версия сборщика.'];if(in_array('limited',[$left['state'],$right['state']],true))return ['state'=>'limited','reason'=>'Сравнение ограничено неполной или неуспешной проверкой.'];return ['state'=>'comparable','reason'=>'Сопоставимая проверенная выборка; выводы только о наблюдениях.'];
    }
    private static function amount(mixed $v):?string {if(!is_string($v)&&!is_int($v))return null;$n=(string)$v;if(!preg_match('/^\d+(?:\.\d+)?$/D',$n)||bccomp($n,'1000000000000000000',8)>0)return null;return $n;}
    private static function price(array $a,array $b,string $field,bool $period=false):array {$old=self::amount($a[$field]??null);$new=self::amount($b[$field]??null);$reason='';if(($a['currency']??$a['price_currency']??'RUB')!=='RUB'||($b['currency']??$b['price_currency']??'RUB')!=='RUB')$reason='Валюта не подтверждена как RUB в обеих карточках.';elseif($old===null||$new===null)$reason='Цена отсутствует или имеет недопустимое значение.';elseif($period&&(($a['price_period']??null)!==($b['price_period']??null)||!in_array($a['price_period']??null,['month','year','day'],true)))$reason='Периоды цены различаются или неизвестны.';
        if($reason)return ['state'=>'insufficient','before'=>$old,'after'=>$new,'delta'=>null,'percent'=>null,'reason'=>$reason];$delta=bcsub($new,$old,8);return ['state'=>bccomp($delta,'0',8)?'changed':'unchanged','before'=>$old,'after'=>$new,'delta'=>$delta,'percent'=>bccomp($old,'0',8)?bcdiv(bcmul($delta,'100',12),$old,6):null,'reason'=>bccomp($old,'0',8)?'':'Процент не вычисляется при исходной цене 0.'];
    }
    private static function event(?array $a,?array $b,string $status,string $reason,array $coverage,?array $price=null,?array $annual=null):array {$r=$b??$a;return ['source'=>$r['source'],'object_type'=>$r['object_type'],'scope'=>$r['scope'],'source_id'=>$r['source_id']??null,'source_url'=>$r['source_url']??null,'address'=>$r['address'],'status'=>$status,'reason'=>$reason,'coverage'=>$coverage,'before'=>$a,'after'=>$b,'price'=>$price,'annual_rate'=>$annual];}
    public static function compare(array $before,array $after):array {
        Market::validate($before);Market::validate($after);if(new \DateTimeImmutable($before['created_at'])>new \DateTimeImmutable($after['created_at']))throw new \RuntimeException('Слева выберите более ранний запуск, справа — более поздний.',422);
        if(isset($before['run_id'],$after['run_id'])&&$before['run_id']===$after['run_id'])foreach(['created_at','settings','records','attempts']as $key)if(Market::canonical($before[$key])!==Market::canonical($after[$key]))throw new \RuntimeException('Разные данные имеют один ID запуска.',409);
        $coverage=[];foreach(Market::SOURCES as $source)foreach(['office','parking']as $kind)foreach(['base','nearby']as $scope)$coverage[$source.'|'.$kind.'|'.$scope]=self::pairCoverage($before,$after,$source,$kind,$scope);
        $urls=[];foreach(array_merge($before['records'],$after['records'])as $r){$u=Market::urlIdentity($r);$id=Market::identity($r);if($u&&$id&&str_contains($id,'|id:'))$urls[$u][$id]=true;}
        $left=[];$right=[];$events=[];foreach([['data'=>$before,'before'=>true],['data'=>$after,'before'=>false]]as $side){foreach($side['data']['records']as $r){$id=Market::identity($r);$url=Market::urlIdentity($r);$cov=$coverage[$r['source'].'|'.$r['object_type'].'|'.$r['scope']];if($url&&count($urls[$url]??[])>1){$events[]=self::event($side['before']?$r:null,$side['before']?null:$r,'ambiguous','У одного URL разные ID; произвольная пара не выбрана.',$cov);continue;}if($url!==null&&$id===$url&&count($urls[$url]??[])===1)$id=array_key_first($urls[$url]);if($id===null){$events[]=self::event($side['before']?$r:null,$side['before']?null:$r,'ambiguous','Нет надёжного ID или уникального URL карточки.',$cov);continue;}if($side['before'])$left[$id][]=$r;else $right[$id][]=$r;}}
        $keys=array_unique(array_merge(array_keys($left),array_keys($right)));sort($keys);foreach($keys as $key){$olds=$left[$key]??[];$news=$right[$key]??[];$row=$news[0]??$olds[0];$cov=$coverage[$row['source'].'|'.$row['object_type'].'|'.$row['scope']];if(count($olds)>1||count($news)>1){foreach($olds as $r)$events[]=self::event($r,null,'ambiguous','Повторяется ключ объявления; однозначная пара не выбрана.',$cov);foreach($news as $r)$events[]=self::event(null,$r,'ambiguous','Повторяется ключ объявления; однозначная пара не выбрана.',$cov);continue;}$a=$olds[0]??null;$b=$news[0]??null;
            if($a&&$b){if($cov['state']==='not_checked'){$events[]=self::event($a,$b,'not_checked',$cov['reason'],$cov);continue;}if(self::address($a['address'])!==self::address($b['address'])||$a['scope']!==$b['scope']){$events[]=self::event($a,$b,'insufficient','У одного ID изменились адрес или область; цена не сопоставлена.',$cov);continue;}$price=self::price($a,$b,'price_rub',true);$annual=self::price($a,$b,'annual_rate_rub_m2');$status=$price['state']==='changed'?'price_changed':($annual['state']==='changed'?'annual_changed':($price['state']==='insufficient'?'insufficient':'unchanged'));$reason=match($status){'price_changed'=>'Изменилась наблюдаемая цена карточки.','annual_changed'=>'Изменилась годовая ставка за м².','insufficient'=>$price['reason'],default=>'Наблюдаемая цена не изменилась.'};$events[]=self::event($a,$b,$status,$reason.($cov['state']!=='comparable'?' '.$cov['reason']:''),$cov,$price,$annual);
            }elseif($cov['state']==='not_checked')$events[]=self::event($a,$b,'not_checked',$cov['reason'],$cov);elseif($cov['state']==='limited')$events[]=self::event($a,$b,$b?'later_only_limited':'earlier_only_limited','Наблюдение относится только к проверенной части выборки. '.$cov['reason'],$cov);else $events[]=self::event($a,$b,$b?'appeared':'not_observed',$b?'Впервые наблюдалось в поздней выборке.':'Не наблюдалось в поздней выборке; это не подтверждает снятие или сдачу.',$cov);
        }
        $priority=array_flip(['price_changed','annual_changed','appeared','not_observed','later_only_limited','earlier_only_limited','insufficient','not_checked','ambiguous','unchanged']);usort($events,fn($a,$b)=>[$priority[$a['status']],$a['source'],$a['object_type'],$a['scope'],(string)$a['source_id'],$a['address']]<=>[$priority[$b['status']],$b['source'],$b['object_type'],$b['scope'],(string)$b['source_id'],$b['address']]);$counts=[];foreach($events as $e)$counts[$e['status']]=($counts[$e['status']]??0)+1;
        return ['schema_version'=>1,'counts'=>$counts,'events'=>$events,'coverage'=>$coverage,'notice'=>'Сравниваются наблюдения объявлений, а не сделки, свободность или полный рынок. Строки без надёжного ключа не объединяются.'];
    }
